@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Nunito:wght@600;700;800;900&display=swap');
:root{font-family:'DM Sans',system-ui,sans-serif;color:#173c3b;font-synthesis:none;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;font-optical-sizing:auto;--ink:#173c3b;--green:#247b69;--cream:#fffaf0;--gold:#ffcf61}
*{box-sizing:border-box}html,body,#game{width:100%;height:100%;height:100dvh;margin:0;overflow:hidden}body{background:#a8e8f0}#game{position:relative;isolation:isolate;touch-action:none}#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;outline:0}
.topbar{position:absolute;left:0;right:0;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:calc(18px + env(safe-area-inset-top)) 28px 0;pointer-events:none}.brand,.mission,.icon-button{pointer-events:auto}.brand{display:flex;align-items:center;gap:10px;font:900 13px 'Nunito',sans-serif;letter-spacing:1.3px;color:#24534c;text-shadow:0 1px 0 #ffffff80}.brand-icon{display:grid;place-items:center;width:39px;height:39px;background:#fff9e8;border:1px solid #fff;border-radius:14px;box-shadow:0 5px 16px #286e5a20;font-size:23px}.brand small{display:block;font:800 9px 'DM Sans',sans-serif;letter-spacing:2px;color:#4e8274;margin-top:1px}.mission{display:flex;align-items:center;gap:8px;padding:10px 15px;border:1px solid #ffffffa8;border-radius:30px;background:#fff9e9c9;color:#37685b;font-size:12px;font-weight:700;box-shadow:0 4px 18px #286e5a15}.mission-dot{width:8px;height:8px;border-radius:50%;background:#76c68d;box-shadow:0 0 0 4px #76c68d30}.icon-button{width:40px;height:40px;border:1px solid #ffffffa8;border-radius:14px;color:#2f675c;background:#fff9e9d9;font-size:17px;font-weight:800;box-shadow:0 4px 18px #286e5a15;cursor:pointer}.hud{position:absolute;z-index:2;left:28px;top:88px;display:flex;align-items:center;gap:12px}.collect-card,.stage-card{display:flex;align-items:center;gap:10px;min-height:48px;padding:8px 13px;border:1px solid #ffffffb8;border-radius:16px;background:#fffaf0df;box-shadow:0 5px 20px #286e5a14;backdrop-filter:blur(8px)}.sunseed-icon{font-size:23px;color:#eda92a;text-shadow:0 2px #ffd978}.collect-card b{font:900 18px 'Nunito',sans-serif;color:#315d4e}.collect-card small{font-size:9px;letter-spacing:1px;font-weight:800;color:#6b8c7c}.stage-card{width:152px;display:grid;gap:5px}.stage-label{font-size:9px;font-weight:800;letter-spacing:1.4px;color:#5a8272}.stage-track{width:100%;height:5px;background:#dce9d8;border-radius:8px;overflow:hidden}.stage-track i{display:block;width:0;height:100%;border-radius:8px;background:linear-gradient(90deg,#eebb4f,#71c88c);transition:width .25s}
.veil{position:absolute;z-index:5;inset:0;display:grid;place-items:center;padding:20px;background:linear-gradient(180deg,#e5f8ee35,#193f403d);backdrop-filter:blur(5px);touch-action:auto}.hidden{display:none!important}.welcome-card{width:min(490px,100%);padding:36px 40px 30px;border:1px solid #ffffffcc;border-radius:28px;background:#fffaf0f2;box-shadow:0 24px 80px #173c3b35;text-align:center;animation:pop .45s cubic-bezier(.2,.8,.2,1) both}.eyebrow{font-size:10px;font-weight:800;letter-spacing:2.1px;color:#6e9a80}.welcome-card h1,.welcome-card h2{margin:11px 0 10px;color:#214c43;font:900 clamp(28px,6vw,43px)/1.04 'Nunito',sans-serif;letter-spacing:-1.6px}.welcome-card h1 span{display:block;color:#ce8c32}.welcome-card p{max-width:350px;margin:0 auto;color:#648274;font-size:14px;line-height:1.6}.howto{display:flex;justify-content:center;gap:21px;margin:25px 0 23px}.howto>div{display:grid;gap:6px;justify-items:center;color:#648274;font-size:10px;font-weight:700}.keycap{padding:5px 7px;border:1px solid #d5e4d4;border-radius:7px;background:#f3f8ed;color:#3e6858;font-size:9px;font-weight:800;letter-spacing:.5px;white-space:nowrap}.play-button{display:flex;align-items:center;justify-content:center;gap:15px;width:100%;min-height:51px;border:0;border-radius:15px;background:linear-gradient(135deg,#3b9a75,#247664);box-shadow:0 7px 0 #1b6257,0 12px 20px #328b6b33;color:white;font:900 12px 'Nunito',sans-serif;letter-spacing:1.5px;cursor:pointer;transition:transform .12s,filter .12s}.play-button:hover{filter:brightness(1.07);transform:translateY(-2px)}.play-button:active{transform:translateY(4px);box-shadow:0 3px 0 #1b6257}.play-button span{font-size:18px}.mobile-note{margin-top:20px;color:#8aa394;font-size:10px}.compact-card{width:min(380px,100%);padding:35px}.compact-card h2{font-size:38px}.text-button{margin-top:20px;padding:8px;border:0;background:none;color:#648274;font:700 12px 'DM Sans',sans-serif;cursor:pointer}.win-card h2 span{color:#ce8c32}.win-sparkle{margin:0 auto 8px;color:#e8ad40;font-size:38px;text-shadow:0 0 15px #f4d57d}.toast{position:absolute;z-index:4;top:145px;left:50%;transform:translate(-50%,-8px);padding:10px 16px;border:1px solid #ffffffc9;border-radius:99px;background:#fffaf0ed;color:#3b705d;font-weight:800;font-size:12px;box-shadow:0 7px 25px #245e4b25;opacity:0;transition:.24s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.loading{position:absolute;inset:auto 0 16px;z-index:6;display:flex;align-items:center;justify-content:center;gap:9px;color:#34715f;font-size:12px;font-weight:700;transition:opacity .3s;pointer-events:none}.loading.done{opacity:0}.loader{width:14px;height:14px;border:2px solid #86b69b;border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite}
.mobile-controls{display:none}.joystick{position:absolute;left:25px;bottom:calc(22px + env(safe-area-inset-bottom));width:124px;height:124px;touch-action:none}.joy-ring{position:absolute;inset:0;border:1px solid #ffffffa8;border-radius:50%;background:#fffaf05c;box-shadow:inset 0 0 0 8px #fffaf026,0 3px 18px #225b4c22}.joy-knob{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px;border:1px solid #ffffffd9;border-radius:50%;background:linear-gradient(145deg,#fffefa,#e5f3df);box-shadow:0 4px 12px #245e4b35;will-change:transform}.jump-button{position:absolute;right:28px;bottom:calc(32px + env(safe-area-inset-bottom));display:grid;place-items:center;align-content:center;gap:1px;width:76px;height:76px;border:2px solid #ffffffd9;border-radius:50%;background:linear-gradient(145deg,#ffdf81,#f1b94c);box-shadow:0 5px 0 #ce9437,0 9px 20px #225b4c25;color:#765122;font-weight:900;touch-action:none}.jump-button span{font-size:27px;line-height:24px}.jump-button small{font:900 8px 'DM Sans',sans-serif;letter-spacing:1px}.jump-button:active{transform:translateY(4px);box-shadow:0 1px 0 #ce9437}
@keyframes spin{to{transform:rotate(360deg)}}@keyframes pop{from{opacity:0;transform:translateY(12px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
@media (pointer:coarse),(max-width:700px){.topbar{padding-left:16px;padding-right:16px}.brand{font-size:11px}.brand-icon{width:35px;height:35px}.mission{font-size:10px;padding:9px 11px}.icon-button{width:36px;height:36px}.hud{left:16px;top:76px;gap:7px}.collect-card,.stage-card{min-height:42px;padding:7px 10px;border-radius:13px}.stage-card{width:116px}.mobile-controls{display:block}.howto{gap:12px}.welcome-card{padding:31px 25px 25px}.welcome-card p{font-size:13px}.mobile-note{margin-top:17px}.toast{top:128px}.loading{bottom:165px}}
@media (max-width:420px){.mission{max-width:150px;overflow:hidden;white-space:nowrap}.stage-card{width:98px}.collect-card small{font-size:8px}.hud{top:69px}.brand small{font-size:8px}.welcome-card h1{font-size:32px}.howto{gap:8px}.keycap{font-size:8px}.joystick{left:18px;width:112px;height:112px}.jump-button{right:22px;width:70px;height:70px}}
@media (min-width:1000px) and (pointer:fine){.mobile-note{display:none}}

